// Controlled demo-data initialization (opt-in, mta-demo.mtaext only). Copies the committed synthetic seed
// (test/data, generated by tools/m04/build-seed.mjs) into db/data BEFORE `cds build --production`, so that CAP
// generates the matching .hdbtabledata files for the HDI deployer; `--clean` removes the copies again.
// A normal production build ships no demo data (test/seed-data.test.js, test/btp-deployment-config.test.js).
import { cpSync, readdirSync, mkdirSync, rmSync, existsSync } from 'node:fs';
import { join } from 'node:path';
const root = join(import.meta.dirname, '..', '..');
const target = join(root, 'db', 'data');
const files = readdirSync(join(root, 'test', 'data')).filter(f => f.endsWith('.csv'));
if (process.argv.includes('--clean')) {
  for (const f of files) rmSync(join(target, f), { force: true });
  if (existsSync(target) && !readdirSync(target).length) rmSync(target, { recursive: true });
  console.log('removed staged demo seed from db/data');
} else {
  mkdirSync(target, { recursive: true });
  for (const f of files) cpSync(join(root, 'test', 'data', f), join(target, f));
  console.log(`staged ${files.length} synthetic seed files (SEED-M04-01 + DS-SCENARIOS-01) into db/data`);
}
